const input = $input.item.json;

return {
  clientName: input.clientName || input.form_response?.answers?.find(a => a.field.ref === 'client_name')?.text,
  clientEmail: input.clientEmail || input.form_response?.answers?.find(a => a.field.ref === 'email')?.email,
  companyName: input.companyName || input.form_response?.answers?.find(a => a.field.ref === 'company')?.text,
  projectDescription: input.projectDescription || input.form_response?.answers?.find(a => a.field.ref === 'project_description')?.text,
  desiredTimeline: input.timeline || 'Not specified',
  budgetRange: input.budget || 'Not specified',
  proposalId: `PROP-${Date.now()}`,
  createdAt: new Date().toISOString()
};

const data = $input.item.json;

const requiredFields = ['clientName', 'clientEmail', 'projectDescription'];
const missing = requiredFields.filter(field => !data[field] || data[field].trim() === '');

if (missing.length > 0) {
  return {
    valid: false,
    missingFields: missing
  };
}

return {
  valid: true,
  data
};

const project = $input.item.json.data || $input.item.json;

const prompt = `Create a detailed proposal breakdown for this project.

**Client:** ${project.clientName}, ${project.companyName}
**Project:** ${project.projectDescription}
**Timeline:** ${project.desiredTimeline}
**Budget:** ${project.budgetRange}

**Your Service:** Automation consulting, $150/hr, $1200/day

Return JSON:
{
  "projectTitle": "Concise project name",
  "executiveSummary": "2-3 sentences",
  "scopeOfWork": {
    "phases": [
      {
        "name": "Phase name",
        "description": "What happens",
        "deliverables": ["deliverable 1"],
        "estimatedHours": number,
        "duration": "X weeks"
      }
    ]
  },
  "pricing": {
    "totalEstimate": number,
    "breakdown": [{"item": "description", "hours": number, "rate": 150, "total": number}],
    "paymentTerms": "50% upfront, 50% on completion"
  },
  "timeline": {
    "totalDuration": "X weeks"
  }
}`;

return {
  prompt,
  project
};

const proposal = $input.item.json.outputJson;
const project = $('Build Proposal Prompt').item.json.project;
const today = new Date().toLocaleDateString('en-US', { year: 'numeric', month: 'long', day: 'numeric' });

const proposalDoc = `# Project Proposal

**${proposal.projectTitle}**

**Prepared for:** ${project.clientName}, ${project.companyName}
**Date:** ${today}
**Proposal ID:** ${project.proposalId}

---

## Executive Summary

${proposal.executiveSummary}

## Scope of Work

${proposal.scopeOfWork.phases.map((phase, i) => `### Phase ${i + 1}: ${phase.name}

${phase.description}

**Deliverables:**
${phase.deliverables.map(d => `- ${d}`).join('
')}

**Duration:** ${phase.duration}`).join('

')}

## Investment

**Total estimate:** $${proposal.pricing.totalEstimate.toLocaleString()}

**Breakdown:**
${proposal.pricing.breakdown.map(item => `- ${item.item}: ${item.hours} hours × $${item.rate}/hour = $${item.total.toLocaleString()}`).join('
')}

**Payment terms:** ${proposal.pricing.paymentTerms}

---

*This proposal is valid for 30 days*`;

return {
  proposalDoc,
  proposalData: {
    ...project,
    ...proposal,
    totalPrice: proposal.pricing.totalEstimate,
    status: 'sent',
    sentAt: new Date().toISOString()
  }
};
